import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Loi Symbiotique du Travail","description":"","frontmatter":{},"headers":[],"relativePath":"fr/41-共生劳动法.md","filePath":"fr/41-共生劳动法.md","lastUpdated":1789183869000}'),n={name:"fr/41-共生劳动法.md"};function o(s,e,l,d,u,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="loi-symbiotique-du-travail" tabindex="-1">Loi Symbiotique du Travail <a class="header-anchor" href="#loi-symbiotique-du-travail" aria-label="Permalink to &quot;Loi Symbiotique du Travail&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>41</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Travail symbiotique, Plus de travail plus de récompense, Droits du travail, Contrat conjoint de production, Anti-exploitation</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi Symbiotique du Travail</em> est l&#39;une des lois fondamentales du système juridique de la Civilisation Symbiotique de l&#39;Ancre, au même rang que la <em>Constitution Symbiotique</em>. Elle vise à réglementer toutes les activités de travail et de contribution au sein de l&#39;Univers Hengyuan, à établir l&#39;ordre de distribution « plus de travail, plus de récompense ; autocroissance et autodéveloppement », et à éradiquer, au niveau juridique, le terreau de l&#39;exploitation prédatrice.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Dignité du travail</td><td>Tout travail licite est protégé par la loi ; la dignité personnelle du travailleur ne doit pas être violée</td></tr><tr><td>Plus de travail, plus de récompense</td><td>La rémunération du travail est directement liée au montant de la contribution ; plus la contribution est grande, plus le revenu est élevé ; le gain sans travail est interdit</td></tr><tr><td>Travail volontaire</td><td>Le travail forcé et l&#39;esclavage sont interdits ; les travailleurs ont le droit de choisir librement le contenu et le mode de travail</td></tr><tr><td>Rémunération équitable</td><td>À travail égal, salaire égal ; la discrimination de rémunération fondée sur la race, la culture ou la naissance est interdite</td></tr><tr><td>Protection du travail</td><td>L&#39;État et la civilisation ont l&#39;obligation de fournir aux travailleurs un environnement de travail sûr et une sécurité sociale de base</td></tr><tr><td>Collaboration symbiotique</td><td>La collaboration et l&#39;entraide entre travailleurs sont encouragées ; la concurrence vicieuse et les jeux à somme nulle sont combattus</td></tr></tbody></table><h2 id="ii-droits-fondamentaux-des-travailleurs" tabindex="-1">II. Droits Fondamentaux des Travailleurs <a class="header-anchor" href="#ii-droits-fondamentaux-des-travailleurs" aria-label="Permalink to &quot;II. Droits Fondamentaux des Travailleurs&quot;">​</a></h2><p>La Loi Symbiotique du Travail confère aux formes de vie dotées de capacité de travail dans l&#39;Univers Hengyuan les droits suivants :</p><ol><li><strong>Droit à l&#39;égalité d&#39;emploi</strong> : aucune vie ne doit subir de discrimination dans la recherche et l&#39;exercice d&#39;un emploi fondée sur la race, la culture, la naissance, le genre ou d&#39;autres facteurs.</li><li><strong>Droit au libre choix du métier</strong> : les travailleurs ont le droit de choisir leur profession, leur poste et leur lieu de travail selon leur volonté et leur capacité, et le droit de changer de métier conformément à la loi.</li><li><strong>Droit à une rémunération raisonnable</strong> : les travailleurs ont le droit de recevoir une rémunération correspondant à leur contribution au travail ; la rémunération ne doit pas être inférieure au niveau minimum de garantie fixé par la civilisation.</li><li><strong>Droit au repos et aux congés</strong> : les travailleurs ont le droit à des aménagements raisonnables du temps de travail et à des congés réguliers ; la prolongation illimitée du temps de travail est interdite.</li><li><strong>Droit à la sécurité du travail</strong> : les travailleurs ont le droit de travailler dans un environnement sûr et hygiénique ; les employeurs doivent fournir des conditions de protection du travail conformes aux normes.</li><li><strong>Droit à la formation professionnelle</strong> : les travailleurs ont le droit de recevoir une formation aux compétences professionnelles et un encadrement de culture ; les employeurs et l&#39;État ont l&#39;obligation de fournir des ressources de formation.</li><li><strong>Droit d&#39;association et de consultation</strong> : les travailleurs ont le droit de constituer ou de rejoindre des associations de travailleurs conformément à la loi, et le droit de protéger leurs intérêts par la négociation collective.</li><li><strong>Droit de recours et de réparation</strong> : lorsque les droits et intérêts du travail sont violés, les travailleurs ont le droit de déposer des recours et des actions auprès des instances d&#39;arbitrage du travail et du Tribunal Symbiotique.</li></ol><h2 id="iii-legalisation-du-mecanisme-de-contrat-conjoint-de-production" tabindex="-1">III. Légalisation du Mécanisme de Contrat Conjoint de Production <a class="header-anchor" href="#iii-legalisation-du-mecanisme-de-contrat-conjoint-de-production" aria-label="Permalink to &quot;III. Légalisation du Mécanisme de Contrat Conjoint de Production&quot;">​</a></h2><p>Le Mécanisme de Contrat Conjoint de Production est l&#39;institution fondamentale de répartition des ressources de la Civilisation Symbiotique de l&#39;Ancre ; la <em>Loi Symbiotique du Travail</em> la fixe sous forme juridique :</p><ul><li><strong>Sujets contractants</strong> : toute vie dotée de capacité de travail peut servir de sujet contractant ; les individus comme les collectifs peuvent contracter.</li><li><strong>Contenu du contrat</strong> : comprend notamment le développement des ressources de culture, l&#39;entretien des plans, la transmission des savoirs, la recherche technologique, les services publics et d&#39;autres domaines.</li><li><strong>Durée du contrat</strong> : déterminée selon la nature du contenu contractuel ; les contrats courts durent de un à trois ans, les contrats longs de cinq à vingt ans, avec possibilité de renouvellement à l&#39;échéance.</li><li><strong>Répartition des revenus</strong> : le revenu du contractant est directement lié à la production ; une partie de la production est reversée à l&#39;accumulation publique, le reste appartient au contractant.</li><li><strong>Mécanisme de sortie</strong> : le contractant a le droit de sortir du contrat après préavis dans un délai raisonnable ; il ne doit pas être contraint de rester dans la relation contractuelle.</li><li><strong>Règlement des litiges</strong> : les litiges contractuels sont réglés en priorité par arbitrage du travail ; en cas de contestation de la sentence arbitrale, il est possible de saisir le Tribunal Symbiotique.</li></ul><h2 id="iv-protection-speciale-du-travail" tabindex="-1">IV. Protection Spéciale du Travail <a class="header-anchor" href="#iv-protection-speciale-du-travail" aria-label="Permalink to &quot;IV. Protection Spéciale du Travail&quot;">​</a></h2><p>En réponse aux besoins particuliers des différentes formes de vie dans l&#39;Univers Hengyuan, cette Loi établit des institutions de protection spéciale du travail :</p><table tabindex="0"><thead><tr><th>Groupe protégé</th><th>Mesures de protection spéciale</th></tr></thead><tbody><tr><td>Cultivateurs débutants</td><td>Aucun travail à haut risque dépassant leurs capacités ne doit être assigné ; un encadrement par mentor est obligatoire</td></tr><tr><td>Vies féminines en période de grossesse et d&#39;accouchement</td><td>Droit à un congé de maternité payé d&#39;au moins six mois ; aucun travail de haute intensité pendant la période d&#39;allaitement</td></tr><tr><td>Vies handicapées et blessées</td><td>Droit à un ajustement raisonnable du poste et à des garanties d&#39;environnement de travail sans obstacles</td></tr><tr><td>Travailleurs d&#39;autres races</td><td>Les employeurs doivent respecter les caractéristiques physiologiques et les coutumes culturelles des races non humaines et fournir des conditions de travail adaptées</td></tr><tr><td>Travailleurs âgés</td><td>Peuvent demander une réduction de l&#39;intensité du travail ou un transfert vers des postes consultatifs après un certain âge</td></tr></tbody></table><h2 id="v-responsabilite-juridique-et-garanties-de-mise-en-œuvre" tabindex="-1">V. Responsabilité Juridique et Garanties de Mise en Œuvre <a class="header-anchor" href="#v-responsabilite-juridique-et-garanties-de-mise-en-œuvre" aria-label="Permalink to &quot;V. Responsabilité Juridique et Garanties de Mise en Œuvre&quot;">​</a></h2><p>Les employeurs qui violent les dispositions de cette Loi supportent les responsabilités suivantes selon la gravité des circonstances :</p><ol><li>Payer la rémunération due au travailleur et les dommages-intérêts (indemnité de une à trois fois les arriérés).</li><li>Se voir ordonner de rectifier dans un délai déterminé ; à défaut, payer une amende.</li><li>Pour les circonstances graves, la licence d&#39;exploitation est révoquée et les personnes responsables sont interdites d&#39;exercer des fonctions de direction pendant une certaine période.</li><li>Pour les infractions pénales, la responsabilité pénale est engagée conformément à la loi.</li></ol><p>L&#39;État établit des institutions d&#39;inspection du travail, chargées de superviser et de contrôler le respect de la loi du travail par les employeurs. Les associations de travailleurs ont le droit de représenter les travailleurs dans l&#39;inspection du travail et la négociation collective.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi Symbiotique du Travail</em> est le vecteur juridique de la philosophie « plus de travail, plus de récompense » de la Civilisation Symbiotique de l&#39;Ancre. Elle transforme le travail d&#39;objet d&#39;exploitation en droit respecté, et la répartition d&#39;appropriation prédatrice en retour fondé sur la contribution, posant des fondations institutionnelles solides pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>06-多劳多得分配原理 (Principes de Répartition Plus de Travail Plus de Récompense)</li><li>22-资源分配联产承包机制 (Mécanisme de Contrat Conjoint de Production pour la Répartition des Ressources)</li><li>42-消费者保护法 (Loi sur la Protection des Consommateurs)</li></ul>',23)])])}const v=t(n,[["render",o]]);export{m as __pageData,v as default};
